def RuleReferencesActiveBus():
    for rid in rule_status:
        if rule_status[rid] == "ENABLED":
            bid = rule_bus[rid]
            if bid in bus_status:
                if bus_status[bid] != "ACTIVE":
                    return False
    return True


# check: every AVAILABLE message belongs to an ACTIVE topic

def MessageRequiresActiveTopic():
    for mid in msg_status:
        if msg_status[mid] == "AVAILABLE":
            tid = msg_topic[mid]
            if tid in topic_status:
                if topic_status[tid] != "ACTIVE":
                    return False
    return True
